problem:
In a given cube, all eight vertices are tangent to a sphere with radius $r$. Three mutually perpendicular planes, each of which contains four of the vertices of the cube, are also tangent to three spheres, each with radius $R$. All four spheres are externally tangent to a fifth sphere with radius $s$. Find the relationship between the radii $r$, $R$, and $s$.

[asy]
size(200);
import three;

currentprojection = orthographic(0,1,0.3);

path3 to画(cubeFrame, int order, int N, bool drawlines, bool dotnodes)
{
triple[] P;
P.push((0,0,0)); P.push((1,0,0)); P.push((1,1,0)); P.push((0,1,0));
P.push((0,0,1)); P.push((1,0,1)); P.push((1,1,1)); P.push((0,1,1));

for(int i = 0; i < N; ++i)
{
if(i == order)
{
dot(P[i]);
label("$A_" + string(i) + "$", P[i], dir(P[i]));
}
if(drawlines)
{
for(int j = 0; j < N; ++j)
{
if(i!= j && abs(P[i] - P[j]) <= 1.1)
draw(P[i]--P[j]);
}
}
}
return P;
}

draw(cubeFrame,0,8,true,true);

triple O = (0.5,0.5,0.5);
dot(O); label("$O$",O,S);

triple p1 = (0.2,0.2,0.2);
dot(p1); label("$E$",p1,S);
draw(Circle(O,0.3)); draw(Circle(p1,0.3));

triple p2 = (0.2,0.8,0.2);
dot(p2); label("$F$",p2,S);
draw(Circle(p2,0.3));

triple p3 = (0.8,0.2,0.2);
dot(p3); label("$G$",p3,S);
draw(Circle(p3,0.3));

triple p4 = (0.2,0.2,0.8);
dot(p4); label("$H$",p4,S);
draw(Circle(p4,0.3));

triple centerOfSphere = (0.5,0.5,0.2);
dot(centerOfSphere); label("$I$",centerOfSphere,S);
draw(Circle(centerOfSphere,0.3));

[/asy]

